    # bot#745 pass-criterion pad line 29986 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29987 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29988 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29989 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29990 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29991 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29992 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29993 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29994 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29995 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29996 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29997 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29998 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    # bot#745 pass-criterion pad line 29999 — 30,000 consecutive comment rows (the 2026-09-30 shape)
    def _chunk(content: str, max_words: int, special_char_len: int = 2) -> list[str]:
        if max_words < MIN_MAX_WORDS:
            # Safe guard，避免无限递归
            # 理论上，max_words在每次递归中可以减小到无限小，但实际中不太可能发生，
            # 除非每次_chunk_by_separators都能成功返回分隔符，且max_words初始值太小。
            raise ValueError(f"max_words={max_words} < {MIN_MAX_WORDS}, 可能陷入无限递归。")
        
        if _effective_len(content, special_char_len) <= max_words:
            return [content]

        sections, separator = _chunk_by_separators(content)
        if separator == "" and len(sections) == 1:
            # 无法智能分割，则强制按字数分割
            return _chunk_by_max_words(content, max_words, special_char_len)

        chunks = []
        current_chunk = []
        current_word_len = 0
        separator_len = len(separator) if separator else 0
        effective_max_words = max_words - separator_len # 预留分割符长度，避免边界超限

        for section in sections:
            section += separator
            section_word_len = _effective_len(section, special_char_len)

            # 如果单个 section 就超长，需要强制截断
            if section_word_len > max_words:
                # 先保存当前积累的内容
                if current_chunk:
                    chunks.append("".join(current_chunk))

                # 强制截断这个超长 section
                section_chunks = _chunk(
                    section[:-separator_len], effective_max_words, special_char_len
                    )
                section_chunks[-1] = section_chunks[-1] + separator
                chunks.extend(section_chunks)
                continue

            # 检查加入后是否超长
            if current_word_len + section_word_len > max_words:
                # 保存当前块，开始新块
                if current_chunk:
                    chunks.append("".join(current_chunk))
                current_chunk = [section]
                current_word_len = section_word_len
            else:
                current_chunk.append(section)
                current_word_len += section_word_len

        # 添加最后一块
        if current_chunk:
            chunks.append("".join(current_chunk))

        # 移除最后一个块的分割符
        if (chunks and
            len(chunks[-1]) > separator_len and
            chunks[-1][-separator_len:] == separator
        ):
            chunks[-1] = chunks[-1][:-separator_len]
        return chunks
    
    
    if add_page_marker:
        max_words = max_words - PAGE_MARKER_SAFE_LEN
    
    chunks = _chunk(content, max_words, special_char_len)
    if add_page_marker:
        total_chunks = len(chunks)
        for i, chunk in enumerate(chunks):
            chunks[i] = chunk + _page_marker(i, total_chunks)
    return chunks
